mapper.update:
update knowledge_base
set knowledge_base_name = #{knowledgeBaseName},
    description = #{description},
    status = #{status},
    updated_at = #{updatedAt}
where id = #{id}

mapper.select:
select id, knowledge_base_name, description, status, created_at, updated_at
from knowledge_base
where id = #{id}

select id, knowledge_base_name, description, status, created_at, updated_at
from knowledge_base
where knowledge_base_name = #{knowledgeBaseName}
  and id != #{id}
limit 1
